from __future__ import annotations

from functools import partial

import pytest
from click.testing import CliRunner

from flask import Blueprint
from flask import Flask
from flask.cli import FlaskGroup


class TestRoutesSubdomains:
    @pytest.fixture
    def app(self):
        app = Flask(__name__)
        app.config["SERVER_NAME"] = "test.local"
        app.testing = True

        admin = Blueprint("admin_blueprint", __name__)

        @admin.route("/home")
        def home():
            pass

        test_sub = Blueprint("test_subdomain_blueprint", __name__)

        @test_sub.route("/home")
        def home():
            pass

        app.register_blueprint(admin, url_prefix="", subdomain="admin")
        app.register_blueprint(test_sub, url_prefix="", subdomain="test")
        return app

    @pytest.fixture
    def invoke(self, app, runner):
        cli = FlaskGroup(create_app=lambda: app)
        return partial(runner.invoke, cli)

    @pytest.fixture
    def runner(self):
        return CliRunner()

    # Reproducer: issue explicitly requests a "Domain" column in the routes output
    def test_domain_column_is_present(self, invoke):
        result = invoke(["routes"])
        assert result.exit_code == 0
        assert "Domain" in result.output

    # Reproducer: issue shows "admin.test.local" as the expected domain for admin routes
    def test_admin_subdomain_domain_shown(self, app, invoke):
        result = invoke(["routes"])
        assert result.exit_code == 0
        assert "admin.test.local" in result.output

    # Reproducer: issue shows "test.test.local" as the expected domain for test subdomain routes
    def test_test_subdomain_domain_shown(self, app, invoke):
        result = invoke(["routes"])
        assert result.exit_code == 0
        assert "test.test.local" in result.output

    # Reproducer: routes without a subdomain should display the default SERVER_NAME
    def test_default_server_name_for_no_subdomain(self, app, invoke):
        result = invoke(["routes"])
        assert result.exit_code == 0
        assert "test.local" in result.output

import pytest
from requests import Request


class TestRequestHooks:

    # Reproducer: issue states passing a list of hooks for a key should register each individually, not wrap the list
    def test_init_accepts_list_of_hooks(self):
        def hook_one(request):
            pass
        def hook_two(request):
            pass

        req = Request(url='http://example.com', hooks={'response': [hook_one, hook_two]})
        assert len(req.hooks['response']) == 2
        assert req.hooks['response'] == [hook_one, hook_two]

    # BVA: a single callable (not a list) must continue to work for backward compatibility
    def test_single_hook_still_works(self):
        def hook_one(request):
            pass

        req = Request(url='http://example.com', hooks={'response': hook_one})
        assert len(req.hooks['response']) == 1
        assert req.hooks['response'] == [hook_one]

    # Reproducer: issue says currently passing a list wraps it, making it uncallable — verify the callable property
    def test_list_hooks_are_callable_after_init(self):
        def hook_one(request):
            pass
        def hook_two(request):
            pass

        req = Request(url='http://example.com', hooks={'response': [hook_one, hook_two]})
        for hook in req.hooks['response']:
            assert callable(hook)

    # Regression: empty hooks dict should still initialize cleanly
    def test_empty_hooks_dict(self):
        req = Request(url='http://example.com', hooks={})
        for event_hooks in req.hooks.values():
            assert isinstance(event_hooks, list)
            assert len(event_hooks) == 0

import numpy as np
import xarray as xr
import pytest


class TestDatasetReprUnits:
    # Reproducer: Dataset repr should show units from attrs next to data variable names
    def test_datavar_units_in_repr(self):
        ds = xr.Dataset(
            {"rainfall": ("time", np.array([1.0, 2.0, 3.0]), {"units": "mm"})},
            coords={
                "time": (
                    "time",
                    np.array(["2000-01-01", "2000-01-02", "2000-01-03"], dtype="datetime64"),
                    {"units": "s"},
                )
            },
        )
        result = repr(ds)
        assert "rainfall" in result
        assert "mm" in result

    # Reproducer: coordinate units should also appear in the repr
    def test_coord_units_in_repr(self):
        ds = xr.Dataset(
            {"rainfall": ("time", np.array([1.0, 2.0, 3.0]), {"units": "mm"})},
            coords={
                "time": (
                    "time",
                    np.array(["2000-01-01", "2000-01-02", "2000-01-03"], dtype="datetime64"),
                    {"units": "s"},
                )
            },
        )
        result = repr(ds)
        assert "time" in result
        assert "s" in result

    # Property: the units string should appear adjacent to the variable name, not hidden elsewhere
    def test_units_appears_near_variable_name(self):
        ds = xr.Dataset(
            {"rainfall": ("time", np.array([1.0, 2.0, 3.0]), {"units": "mm"})},
            coords={
                "time": (
                    "time",
                    np.array(["2000-01-01", "2000-01-02", "2000-01-03"], dtype="datetime64"),
