        result = repr(ds)
        assert "mm" in result
        assert "s" in result

import pytest


# Reproducer: all() with generator expression produces useless error message
def test_all_generator_reports_failure():
    def is_even(x):
        return x % 2 == 0

    even_stevens = list(range(1, 100, 2))
    with pytest.raises(AssertionError) as excinfo:
        assert all(is_even(number) for number in even_stevens)


# Reproducer: any() with generator expression also lacks detail
def test_any_generator_reports_failure():
    def is_odd(x):
        return x % 2 == 1

    odd_stevens = list(range(0, 100, 2))
    with pytest.raises(AssertionError) as excinfo:
        assert any(is_odd(number) for number in odd_stevens)


# Reproducer: list comprehension inside all() lacking element-level detail
