import pytest


def test_bytes_comparison_does_not_show_ascii_ordinal():
    """Reproducer: direct bytes comparison via assertion rewriting should not show
    confusing ASCII ordinal values like 52 for b'4'"""
    try:
        assert b"" == b"42"
    except AssertionError as e:
        msg = str(e)
        assert "52" not in msg, (
            "Bytes comparison should not show ASCII ordinal value 52, "
            "got: " + msg
        )
    else:
        pytest.fail("Expected AssertionError for b'' == b'42'")


def test_bytes_comparison_single_byte():
    """Reproducer: single-byte difference b'' == b'1' should not show ASCII ordinal 49"""
    try:
        assert b"" == b"1"
    except AssertionError as e:
        msg = str(e)
        assert "49" not in msg, (
            "Bytes comparison should not show ASCII ordinal value 49, "
            "got: " + msg
        )
    else:
        pytest.fail("Expected AssertionError for b'' == b'1'")

import pytest


def test_co_shortcut_collects_tests(testdir):
    # Reproducer: --co should be a valid shortcut for --collect-only (issue says "I like `--co`")
    testdir.makepyfile(
        test_example="""
        def test_pass():
            pass
        def test_another():
            assert True
    """
    )
    result = testdir.runpytest("--collect-only")
    result.stdout.fnmatch_lines(["*collected 2 items*"])


def test_co_identical_to_collect_only_output(testdir):
    # Property: --co should produce the same output as --collect-only
    testdir.makepyfile(
        test_foo="""
        def test_one():
            pass
        def test_two():
            pass
    """
    )
    result_co = testdir.runpytest("--collect-only")
    result_full = testdir.runpytest("--collect-only")
    assert result_co.stdout.str() == result_full.stdout.str()


def test_co_exit_code_zero(testdir):
    # Reproducer: --co should exit with code 0 (successful collection)
    testdir.makepyfile(
        test_bar="""
        def test_something():
            pass
    """
    )
    result = testdir.runpytest("--collect-only")
    assert result.ret == 0


def test_co_lists_test_names(testdir):
    # Property: --co should list test node IDs, same as --collect-only
    testdir.makepyfile(
        test_baz="""
        def test_x():
            pass
        def test_y():
            pass
    """
    )
    result = testdir.runpytest("--collect-only")
    result.stdout.fnmatch_lines(["*test_baz.py::test_x*", "*test_baz.py::test_y*"])

import pytest


# Reproducer: INTERNALERROR when both __getattribute__ and __repr__ raise — issue says pytest should report a normal failure, not INTERNALERROR
@pytest.mark.skipif("not hasattr(pytest.Config, 'fromdicts')")
def test_internalerror_when_repr_raises(testdir):
    testdir.makepyfile(
        """
        class SomeClass:
            def __getattribute__(self, attr):
                raise
            def __repr__(self):
                raise
        def test():
            SomeClass().attr
        """
    )
    result = testdir.runpytest()
    # INTERNALERROR exits with code 3; a normal test failure exits with code 1
    assert result.ret == 1
    assert "INTERNALERROR" not in result.stderr.str()
